#nullable enable // autogenerated  
  
using MVZ2.GameContent.Effects;  
using MVZ2.Vanilla.Audios;  
using MVZ2.Vanilla.Entities;  
using MVZ2Logic.Entities;  
using MVZ2Logic.Level;  
using PVZEngine.Definitions;  
using PVZEngine.Entities;  
using UnityEngine;  
  
namespace MVZ2.GameContent.Projectiles  
{  
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.EnderPearl)]  
    public class EnderPearl : EntityBehaviourDefinition  
    {  
        public EnderPearl(string nsp, string name) : base(nsp, name) { }  
  
        public override void Init(Entity entity)  
        {  
            base.Init(entity);  
            // 与手雷一致：不与任何东西碰撞，仅靠“落地”判定触发效果  
            entity.CollisionMaskHostile = 0;  
            entity.CollisionMaskFriendly = 0;  
        }  
  
        public override void Update(Entity projectile)  
        {  
            base.Update(projectile);  
            // 落地（相对地面高度 <= 0）时把矿车传送到落点，然后移除珍珠  
            if (projectile.GetRelativeY() <= 0)  
            {  
                TeleportCart(projectile);  
                projectile.Remove();  
            }  
        }  
  
        private void TeleportCart(Entity pearl)  
        {  
            var level = pearl.Level;  
            // 取场上唯一矿车（重装兵器关卡由 FindSingleCart 保证单例）  
            var cart = MinecartRideable.FindSingleCart(level);  
            if (cart == null || !cart.ExistsAndAlive())  
                return;   // 没有矿车（非重装兵器环境）则不产生任何效果  
  
            // 目标落点：珍珠着地处的 x/z，y 贴合地面高度  
            var dest = pearl.Position;  
            dest.y = level.GetGroundY(dest.x, dest.z);  
  
            // 传送前在原位置生成烟雾特效  
            cart.Spawn(VanillaEffectID.smokeCluster, cart.GetCenter());  
  
            // 关键：位置 + 目标点必须一起设置！  
            // 否则 MinecartRideable.Update 会用 FollowPointer 把矿车  
            // 平滑拉回旧目标点，导致传送“失效”。  
            cart.Position = dest;  
            MinecartRideable.SetTargetPosition(cart, dest);  
            cart.Velocity = Vector3.zero;  
  
            // 传送后在新位置生成烟雾并播放末影人传送音效  
            cart.Spawn(VanillaEffectID.smokeCluster, cart.GetCenter());  
            cart.PlaySound(VanillaSoundID.EndermanTeleport);  
  
            // 注意：矿车上的器械（rider）无需手动移动——RidingPassengerBuff  
            // 每帧执行 UpdatePassengerPosition，会自动贴到矿车新位置，不会断连。  
        }  
    }  
}
